// Repeated, type-specific shapes we want to avoid
int SelectGreaterInt(int left, int right)
DateTime SelectGreaterDateTime(DateTime left, DateTime right)

// One generic shape preserves whichever type the caller supplies
T SelectGreater<T>(T left, T right)

private static T SelectGreater<T>(T left, T right)
//             ↑       ↑       ↑
//          returns T  both inputs are the same T

private static T SelectGreater<T>(T left, T right)
    where T : IComparable<T>
//            └─ T must support CompareTo(T other)

int comparison = left.CompareTo(right);

// comparison < 0  → right is later/higher
// comparison == 0 → values are equal; return left
// comparison > 0  → left is later/higher
return comparison >= 0 ? left : right;

int higherId = SelectGreater(firstEntry.EmployeeId, secondEntry.EmployeeId);
// T is inferred as int

DateTime laterClockIn = SelectGreater(firstEntry.ClockIn, secondEntry.ClockIn);
// T is inferred as DateTime

int higherId = Math.Max(firstId, secondId);
DateTime laterClockIn = firstClockIn >= secondClockIn
    ? firstClockIn
    : secondClockIn;

// SelectGreater<T> remains valuable here because the goal is to learn generics.

