// ScratchPad/Session14/Session14GenericMethodDemo.cs
public sealed class Session14GenericMethodDemo
{
    public void Run()
    {
        var firstEntry = new ClockEntry(
            14,
            new DateTime(2026, 1, 14, 8, 0, 0));

        var secondEntry = new ClockEntry(
            27,
            new DateTime(2026, 1, 14, 9, 30, 0));

        int higherEmployeeId = SelectGreater(
            firstEntry.EmployeeId,
            secondEntry.EmployeeId);

        DateTime laterClockIn = SelectGreater(
            firstEntry.ClockIn,
            secondEntry.ClockIn);

        Console.WriteLine($"Higher employee ID: {higherEmployeeId}");
        Console.WriteLine($"SelectGreater clock-in: {laterClockIn}");
    }

    private static T SelectGreater<T>(T left, T right)
        where T : IComparable<T>
    {
        int comparison = left.CompareTo(right);
        return comparison >= 0 ? left : right;
    }
}

